/**
 * Execution types for plugin-hosted experiment runs.
 * These define the minimal surface shared between core, main process,
 * preload bridge, and renderer for M2/M3 execution.
 */

export type ExecutionStatus = 'pending' | 'running' | 'passed' | 'failed' | 'cancelled' | 'timeout';

/**
 * Describes what to run: which plugin, which experiment, in which package directory.
 * Main process validates this before spawning anything.
 */
export interface ExecutionPlan {
  /** Unique ID for this execution attempt — generated by renderer, echoed back in all events. */
  executionId: string;
  /** The experiment's lab ID as declared in the markdown. */
  labId: string;
  /** Chapter the experiment belongs to, for history recording. */
  chapterId: string;
  /** Plugin ID that handles this experiment type. */
  pluginId: string;
  /** Absolute path of the package (must already be trusted). */
  packageDir: string;
  /** Experiment type, e.g. "query" or "io-match". Passed to the plugin. */
  experimentType: string;
  /** Freeform input the user provided, if any. */
  input?: string;
  /** Max milliseconds before the host forcibly kills the process. Default 30000. */
  timeoutMs?: number;
}

export interface ExecutionPlanError {
  type:
    | 'invalid_plan'
    | 'plugin_not_found'
    | 'plugin_missing_entrypoint'
    | 'package_not_trusted'
    | 'execution_already_running';
  message: string;
}

/**
 * Streamed output event from the host to the renderer.
 * Each event carries the executionId so the renderer can route it.
 */
export interface ExecutionOutputEvent {
  executionId: string;
  channel: 'stdout' | 'stderr';
  text: string;
}

/**
 * Completion event sent when the process exits or times out.
 */
export interface ExecutionCompleteEvent {
  executionId: string;
  status: 'passed' | 'failed' | 'cancelled' | 'timeout';
  exitCode?: number;
  durationMs: number;
  /** Structured step results from the plugin's stdout JSON, if any. */
  steps?: Array<{ name: string; status: 'passed' | 'failed' | 'skipped'; message?: string }>;
  /** Human-readable error or verdict reason. */
  reason?: string;
}
